export function Issue({
  id = "{{id}}",
  title = "{{title}}",
  type = "{{type}}",
  assignee = "{{assignee}}",
  resolved = {{resolved}},
}) {
  const palette = {
    bug: { background: "color-mix(in srgb, #E8A020 25%, #FAF7F2)", color: "#7a5410", icon: <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><circle cx="8" cy="9" r="4" /><path d="M8 5V3M5 4 4 3M11 4l1-1M4 9H2M14 9h-2M5 13l-1 1M11 13l1 1" /></svg> },
    task: { background: "color-mix(in srgb, #BFD9F2 45%, #FAF7F2)", color: "#1f4266", icon: <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><rect x="2" y="2" width="12" height="12" rx="2" /><path d="M5 8.5 7 10.5 11 6" /></svg> },
    improvement: { background: "color-mix(in srgb, #A8E6C1 45%, #FAF7F2)", color: "#205c37", icon: <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><path d="M2 12l4-4 3 3 5-6" /><path d="M11 4h3v3" /></svg> },
  }[type] ?? {};
  return (
    <article aria-label={"Issue " + id + ": " + title} style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: "10px 16px", maxWidth: 540, padding: "16px 18px", borderRadius: 12, background: "#FAF7F2", border: "1px solid #24143022", font: "14px/1.4 system-ui, sans-serif", color: "#241430", boxSizing: "border-box" }}>
      <span style={{ font: "700 12px/1 ui-monospace, monospace", background: "#24143012", padding: "4px 8px", borderRadius: 6 }}>{id}</span>
      <span style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "4px 9px", borderRadius: 999, font: "600 12px/1 system-ui, sans-serif", textTransform: "capitalize", background: palette.background, color: palette.color }}>
        {palette.icon}
        <span>{type}</span>
      </span>
      <h3 style={{ flexBasis: "100%", margin: 0, fontWeight: 600, fontSize: 15 }}>{title}</h3>
      <p style={{ margin: 0, fontSize: 13, color: "#241430b3" }}>Assigned to {assignee}</p>
      {resolved ? (
        <span style={{ marginLeft: "auto", display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, fontWeight: 600, padding: "4px 9px", borderRadius: 999, background: "color-mix(in srgb, #A8E6C1 45%, #FAF7F2)", color: "#205c37" }}>
          <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><circle cx="8" cy="8" r="6.3" /><path d="M5.3 8.2 7 9.9l3.6-4" /></svg>
          Resolved
        </span>
      ) : (
        <span style={{ marginLeft: "auto", display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, fontWeight: 600, padding: "4px 9px", borderRadius: 999, background: "color-mix(in srgb, #D9C8F0 45%, #FAF7F2)", color: "#4a3a68" }}>
          <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><circle cx="8" cy="8" r="6.3" /><path d="M8 4.5v4.2M8 11.5v.1" /></svg>
          Open
        </span>
      )}
    </article>
  );
}
